@staticmethod
def _tool_entry_name(entry: Any) -> str:
    """Return the tool name from Helix's prompt/tool schema entry."""
    if isinstance(entry, str):
        return entry

    if not isinstance(entry, dict):
        return ""

    for key in ("name", "tool"):
        value = entry.get(key)
        if isinstance(value, str):
            return value

    function = entry.get("function")
    if isinstance(function, dict):
        value = function.get("name")
        if isinstance(value, str):
            return value

    return ""

def _available_tools_for_state(
    self,
    state: AgentState,
) -> list[Any]:
    """Expose only tools that are legal/useful in the current state."""
    active = self._active_staged_file(state)

    if active:
        characters = state.staged_files.get(active, 0)

        if characters == 0:
            allowed = {
                "append_file",
                "append_file_raw",
            }
        else:
            allowed = {
                "append_file",
                "append_file_raw",
                "read_file",
                "finish_file",
            }

        return [
            entry
            for entry in TOOLS
            if self._tool_entry_name(entry) in allowed
        ]

    if state.post_finish_pending:
        # A file was just completed. Do not let the model waste the
        # continuation step rediscovering the repository or invoking
        # staged-file operations when no staged file exists.
        blocked = {
            "list_files",
            "read_file",
            "append_file",
            "append_file_raw",
            "finish_file",
        }

        filtered = [
            entry
            for entry in TOOLS
            if self._tool_entry_name(entry) not in blocked
        ]

        # Defensive fallback: never accidentally send an empty tool list
        # if a future tool-schema format changes.
        return filtered or TOOLS

    return TOOLS

def test_available_tools_are_state_filtered_in_prompt(self):
    source = Path(helix.__file__).read_text(encoding="utf-8")

    self.assertIn(
        '"available_tools": self._available_tools_for_state(state)',
        source,
    )
    self.assertIn(
        '"append_file_raw",',
        source,
    )
    self.assertIn(
        '"finish_file",',
        source,
    )
    self.assertIn(
        '"list_files",',
        source,
    )

def test_tool_entry_name_supports_common_schema_shapes(self):
    self.assertEqual(
        helix.HelixAgent._tool_entry_name("read_file"),
        "read_file",
    )
    self.assertEqual(
        helix.HelixAgent._tool_entry_name(
            {"name": "begin_file"}
        ),
        "begin_file",
    )
    self.assertEqual(
        helix.HelixAgent._tool_entry_name(
            {"function": {"name": "run_command"}}
        ),
        "run_command",
    )
